SELECT b.id, b.name, b.location, b.length_meters, b.length_feet
FROM bridge b
WHERE b.length_meters > 70;

SELECT architect.id, architect.name
FROM architect
WHERE architect.gender = 'female';

SELECT m.id, m.name, m.location, m.type, m.built_year, m.notes
FROM mill m
WHERE m.location LIKE '%CH%';

SELECT m.id, m.location, m.name, m.type, m.built_year, m.notes
FROM mill m
WHERE m.notes LIKE '%Molenechos (Dutch)%';

SELECT name
FROM bridge
WHERE length_meters > 80;

SELECT m.name, m.built_year
FROM mill m
WHERE m.type = 'Bergmolen';

SELECT "name", "length_feet"
FROM "bridge"
WHERE "id" = 1;

SELECT architect_id, mill_count
FROM architect_mill_stats
WHERE architect_id = 1;

SELECT m.name, m.location
FROM mill m
WHERE m.built_year < 1830;

SELECT b.id, b.name, b.location, b.length_meters, b.length_feet
FROM bridge b
WHERE b.length_meters > 200 OR b.length_feet > 200;

SELECT name
FROM bridge
WHERE location LIKE '%China%';

SELECT a.name
FROM architect a
WHERE a.nationality2 = 'American';

SELECT a.id, a.name, a.nationality1, a.nationality2
FROM architect a
WHERE a.nationality1 = 'British' OR a.nationality2 = 'British';

SELECT b.name, b.length_feet
FROM bridge b
ORDER BY b.length_feet ASC;

SELECT b.id, b.name, b.location, b.length_meters, b.length_feet
FROM bridge b
WHERE b.architect_id = 2;

SELECT b.id, b.name, b.location, b.length_meters, b.length_feet
FROM bridge b
WHERE b.location LIKE '%Afghanistan%';

SELECT m.id, m.name, m.location, m.type, m.built_year
FROM mill m
WHERE m.built_year - YEAR(CURRENT_DATE) > 150;

SELECT b.id, b.name, b.location, b.length_meters, b.length_feet
FROM bridge b
WHERE b.length_meters > 80 OR b.length_feet > 250;

SELECT a.id, a.name, a.nationality1, a.nationality2
FROM architect a
WHERE a.nationality1 != '' OR a.nationality2 != '';

SELECT b.id, b.name, b.location, b.length_meters, b.length_feet
FROM bridge b
WHERE b.length_meters BETWEEN 65 AND 75;

SELECT m.id, m.name, m.location, m.type, m.built_year
FROM mill m
WHERE m.built_year < 1800;

SELECT b.name, b.location
FROM bridge b
WHERE b.architect_id = 5;

SELECT MAX(MAX(COALESCE(bridge.length_meters, 0))) AS max_span_meters,
       MAX(MAX(COALESCE(bridge.length_feet, 0))) AS max_span_feet
FROM bridge;

SELECT m.id, m.name, m.location, m.type, m.built_year, m.notes
FROM mill m
WHERE m.location LIKE '%Belgium%';

SELECT a.id, a.name, a.nationality1, a.nationality2
FROM architect a
WHERE a.nationality1 LIKE '%American%' OR a.nationality2 LIKE '%American%';

SELECT "name", "type", "notes"
FROM mill
WHERE "name" = 'Le Vieux Molen';

SELECT m.id, m.name, m.location, m.type, m.built_year
FROM mill m
WHERE m.built_year BETWEEN 1837 AND 1900;

SELECT a.id, a.name, a.nationality1
FROM architect a
WHERE a.nationality2 IS NULL;

SELECT b.id, b.name, b.location, b.length_meters, b.length_feet
FROM bridge b
JOIN architect a ON b.architect_id = a.id
WHERE a.name = 'Frank Gehry' OR a.name = 'Canadian' AND a.id IN (
    SELECT architect_id FROM architect WHERE nationality1 = 'Canadian' OR nationality2 = 'Canadian'
);

SELECT b.id, b.name, b.location, b.length_meters, b.length_feet
FROM bridge b
WHERE b.length_meters > 200 OR b.length_feet > 200;

SELECT b.name
FROM bridge b
WHERE b.length_meters BETWEEN 70 AND 80;

SELECT b.id, b.name, b.location, b.length_meters, b.length_feet
FROM bridge b
WHERE b.location LIKE '%Chad%';

SELECT architect_id
FROM architect_mill_stats
WHERE mill_count = 2;

SELECT b.id, b.name, b.location, b.length_meters, b.length_feet
FROM bridge b
WHERE b.length_meters = 65 OR b.length_feet = 65;

SELECT m.id, m.name, m.location, m.type, m.built_year
FROM mill m
WHERE m.built_year BETWEEN 1850 AND 1899;

SELECT name
FROM architect
WHERE nationality2 = '';

SELECT m.id, m.name, m.location, m.notes
FROM mill m
WHERE m.notes LIKE '%Molenechos (Dutch)%';

SELECT b.id, b.name, b.location, b.length_meters, b.length_feet
FROM bridge b
WHERE b.length_meters < 70 OR b.length_feet < 70;

SELECT avg_built_year
FROM architect_mill_stats
WHERE architect_id IN (
    SELECT id FROM architect WHERE name = 'Frank Lloyd Wright'
);

SELECT m.id, m.name, m.location, m.type, m.built_year
FROM mill m
WHERE m.built_year >= 1800 AND m.built_year < 1900;
